INSERT INTO `t_measure_method` VALUES ('2c8792053e0dbcc74fae8d9b77f866f6', NULL, NULL, '8d838536-4736-11f0-9ab5-40c2baa93bfc', 'GB 8538-2022-亚硝酸盐-41.1', '定量测定', '{\"qcParams\": [], \"curveType\": \"1\", \"energyLamp\": \"\", \"repeatMode\": \"不重复\", \"waveLength\": [\"540\"], \"repeatCount\": \"\", \"approxParams\": [], \"curveFormula\": \"C=k1(Abs)+k0\", \"equationType\": \"f_Abs\", \"responseTime\": \"0.5\", \"resultParams\": [], \"timeInterval\": \"\", \"curveTypeName\": \"一次曲线\", \"coefficientMode\": \"standard\", \"equationTypeName\": \"C=f(Abs)\", \"waveLengthParams\": [\"1\"], \"coefficientParams\": [], \"sampleInputParams\": [{\"unit\": \"Abs\", \"paramName\": \"540\", \"resultIdentity\": \"A\"}, {\"unit\": \"mg/L\", \"paramName\": \"所取水样的体积，mL\", \"resultIdentity\": \"V\"}, {\"unit\": \"mg/L\", \"paramName\": \"从校准曲线得到的亚硝酸盐（以NO2计）的质量（μg）\", \"resultIdentity\": \"m\"}], \"spectralBandwidth\": \"2\", \"waveLengthFormula\": \"Abs=Abs[540nm]\", \"statisticalContent\": [], \"coefficientModeName\": \"标准曲线法\", \"changeLampWaveLength\": \"361\", \"preProcessParameters\": [\"试验步骤\\n11 若水样浑浊或色度较深，可先取 100 mL，加入 2 mL 氢氧化铝悬浮液，搅拌后静置数分钟，过滤。\\n2 先将水样或处理后的水样用酸或碱调近中性。取 50.0 mL 置于比色管中。\\n3 另取 50 mL 比色管 8 支，分别加入亚硝酸盐（以 N 计）标准溶液 0 mL、0.50 mL、1.00 mL、2.50 mL、5.00 mL、7.50 mL、10.00 mL 和 12.50 mL，用纯水稀释至 50 mL。\\n4 向水样及标准色列管中分别加入 1 mL 对氨基苯磺酰胺溶液（10 g/L），摇匀后放置 2 min～8 min。加入 1.0 mL 盐酸 N -（1 - 萘基） - 乙二胺溶液（1.0 g/L），立即混匀。\\n5 于 540 nm 波长，用 1 cm 比色皿，以纯水作参比，在 10 min～2 h 内，测定吸光度。如亚硝酸盐（以 NO2 计）质量浓度低于 13 μg/L 时，改用 3 cm 比色皿。\"], \"referenceStandardName\": \"食品安全国家标准 饮用天然矿泉水检验方法\"}', NULL, '2025-11-05 09:03:02', 'kh-admin', NULL, NULL, NULL, NULL);
INSERT INTO `t_measure_method` VALUES ('408b118ef86fc07ba7f4d959acbf120a', NULL, NULL, '8d838536-4736-11f0-9ab5-40c2baa93bfc', '定量测定默认方法', '定量测定', '{\"gain\": 1, \"qcParams\": [], \"curveType\": \"1\", \"energyLamp\": \"0\", \"repeatMode\": \"不重复\", \"waveLength\": [\"660\"], \"approxParams\": [], \"equationType\": \"f_C\", \"responseTime\": \"0.5\", \"resultParams\": [], \"timeInterval\": \"0\", \"curveTypeName\": \"一次曲线\", \"samplePoolWay\": \"1\", \"energyLampName\": \"钨灯\", \"coefficientMode\": \"standard\", \"differentialMode\": \"no_differential\", \"equationTypeName\": \"Abs=f(C)\", \"waveLengthParams\": [\"1\"], \"sampleInputParams\": [], \"spectralBandwidth\": \"2\", \"waveLengthFormula\": \"Abs=660Abs\", \"coefficientModeName\": \"标准曲线法\", \"changeLampWaveLength\": \"361\", \"differentialModeName\": \"不微分\"}', NULL, '2025-09-16 10:48:09', 'kh-admin', NULL, NULL, NULL, NULL);
INSERT INTO `t_measure_method` VALUES ('9c78eb4ad59ef9665c60d3c9d719b27a', NULL, NULL, '8d838536-4736-11f0-9ab5-40c2baa93bfc', '鸡精调味料', '光度测量', '{\"qcParams\": [], \"energyLamp\": \"\", \"luminosity\": \"1\", \"waveLength\": [\"250\"], \"approxParams\": [{\"resultIdentity\": \"X3\", \"roundingParams\": [{\"id\": \"row_81\", \"lowerLimit\": -10, \"roundingType\": \"1\", \"decimalPlaces\": 3}], \"resultIdentityName\": \"呈味核苷酸二钠含量\"}], \"responseTime\": \"0.5\", \"resultParams\": [{\"unit\": \"g/100g\", \"resultName\": \"呈味核苷酸二钠含量\", \"formulaText\": \"X3=(A*530*2000)/(m3*11950*1000)*100\", \"resultIdentity\": \"X3\"}], \"timeInterval\": \"0\", \"luminosityName\": \"Abs\", \"repetitionTime\": \"2\", \"repetitionPattern\": \"不重复\", \"sampleInputParams\": [{\"unit\": \"g/100g\", \"paramName\": \"试样溶液在250nm 处测得的吸光度;\", \"resultIdentity\": \"A\"}], \"spectralBandwidth\": \"2\", \"changeLampWaveLength\": \"361\", \"preProcessParameters\": [\"分析步骤\\n准确称取均匀的样品 2g~4g，用少量 0.01mol/L 的盐酸溶液溶解，定容于 100mL 的容量瓶中，混匀，过滤，弃去初滤液，吸取滤液 5.00mL 于 100mL 的容量瓶，用 0.01mol/L 的盐酸溶液定容，混匀，此溶液即为测试液。\\n将测试液注入10mm的石英比色皿中，以0.01mol/L的盐酸溶液作空白，测其在波长250nm下的吸光度。\"], \"referenceStandardName\": \"鸡精调味料\"}', NULL, '2025-11-05 09:23:54', 'kh-admin', NULL, NULL, NULL, NULL);
INSERT INTO `t_measure_method` VALUES ('d801956f2d9eae0a95d98f5d166c268d', NULL, NULL, '8d838536-4736-11f0-9ab5-40c2baa93bfc', '芦荟含量测试', '光度测量', '{\"qcParams\": [{\"controlType\": \"平行样重复性\"}], \"energyLamp\": \"\", \"luminosity\": \"1\", \"waveLength\": [\"512\"], \"approxParams\": [{\"resultIdentity\": \"X3\", \"roundingParams\": [{\"id\": \"row_101\", \"lowerLimit\": -5, \"upperLimit\": 100, \"roundingType\": \"1\", \"decimalPlaces\": 3}], \"resultIdentityName\": \"样品的芦荟苷含量\"}], \"responseTime\": \"0.5\", \"resultParams\": [{\"unit\": \"mg/L或mg/kg\", \"resultName\": \"样品的芦荟苷含量\", \"formulaText\": \"X3=(41.67 * A * V5 * V7)/(V6 * V8)\", \"resultIdentity\": \"X3\"}], \"timeInterval\": \"0\", \"luminosityName\": \"Abs\", \"repetitionTime\": \"2\", \"repetitionPattern\": \"不重复\", \"sampleInputParams\": [{\"unit\": \"Abs\", \"paramName\": \"512\", \"resultIdentity\": \"A\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"所移取的0.5%醋酸镁甲醇溶液的体积(mL)\", \"resultIdentity\": \"V5\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"用CCl4定容的体积\", \"resultIdentity\": \"V7\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"所移取的CCl4萃取液的体积(mL)\", \"resultIdentity\": \"V6\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"移取液体的体积(mL)\", \"resultIdentity\": \"V8\"}], \"spectralBandwidth\": \"2\", \"changeLampWaveLength\": \"361\", \"preProcessParameters\": [\"准确移取一定量的液体样品，或称取一定量的固体样品（精确至0.0001g）加适量热水超声波萃取后，加到盛有60%FeCl3溶液1.0mL,盐酸6mL的150mL回流瓶中混匀，至沸水浴中加热回流4h，放冷，移至150mL分液漏斗中。用1mol/L NaOH溶液4mL和蒸馏水4mL依次洗涤回流瓶，一并倒入分液漏斗中。用CCl4定容至刻度，摇匀。准确吸取一定量的萃取液，置水浴上小心蒸干。准确吸取0.5%醋酸镁甲醇溶液10mL使之溶解。\"], \"referenceStandardName\": \"化妆品用芦荟汁、粉\"}', NULL, '2025-11-04 22:13:40', 'kh-admin', NULL, NULL, NULL, NULL);
INSERT INTO `t_measure_method` VALUES ('ddef507cf0be50cff93a41fc3ffe73ca', NULL, NULL, '8d838536-4736-11f0-9ab5-40c2baa93bfc', '甲醛浓度', '定量测定', '{\"qcParams\": [], \"curveType\": \"1\", \"energyLamp\": \"\", \"repeatMode\": \"不重复\", \"waveLength\": [\"574\"], \"repeatCount\": \"\", \"approxParams\": [{\"resultIdentity\": \"fitConcentration\", \"roundingParams\": [{\"id\": \"row_118\", \"lowerLimit\": -5, \"upperLimit\": 100, \"roundingType\": \"2\", \"decimalPlaces\": 2}], \"resultIdentityName\": \"拟合浓度\"}], \"curveFormula\": \"Abs=k1(C)+k0\", \"equationType\": \"f_C\", \"responseTime\": \"0.5\", \"resultParams\": [{\"unit\": \"mg/kg或 mg/L\", \"resultName\": \"食品模拟物中甲醛的浓度\", \"formulaText\": \"ρ=(y-b)/a\", \"resultIdentity\": \"ρ\"}], \"timeInterval\": \"\", \"curveTypeName\": \"一次曲线\", \"samplePoolWay\": \"1\", \"equationTypeName\": \"Abs=f(C)\", \"coefficientParams\": [], \"sampleInputParams\": [{\"unit\": \"Abs\", \"paramName\": \"574\", \"resultIdentity\": \"A\"}, {\"unit\": \"mg/kg或 mg/L\", \"paramName\": \"标准工作曲线的斜率。\", \"resultIdentity\": \"a\"}, {\"unit\": \"mg/kg或 mg/L\", \"paramName\": \"食品模拟物中甲醛的吸光值\", \"resultIdentity\": \"y\"}, {\"unit\": \"mg/kg或 mg/L\", \"paramName\": \"标准工作曲线的截距\", \"resultIdentity\": \"b\"}], \"spectralBandwidth\": \"2\", \"waveLengthFormula\": \"Abs=Abs[574nm]\", \"statisticalContent\": [], \"changeLampWaveLength\": \"361\", \"preProcessParameters\": [\"迁移试验\\n根据待测样品的预期用途和使用条件，按照GB5009.165和GB31604.1的要求，对样品进行迁移试验。迁移试验过程中至测定前，应注意密封，以避免甲醛的挥发损失。同时作空白试验。\\n显色反应\\n分别吸取1.0mL模拟物试样溶液、空白溶液至10mL比色管中，各加入1.0mL变色酸溶液，再缓慢加入8.0mL硫酸溶液，小心摇动比色管。溶液充分摇匀后，将比色管置90℃水浴中20min，立即在冰水浴中冷却2min，然后取出并恢复至室温。\"], \"referenceStandardName\": \"食品安全国家标准 食品接触材料及制品 甲醛迁移量的测定\"}', NULL, '2025-11-05 09:05:52', 'kh-admin', NULL, NULL, NULL, NULL);
