INSERT INTO `t_report_calculation_formulas` VALUES (2476, '2516', 'X', '试样中抗氧化剂的含量', 'mg/kg', '样液中PG的质量,单位为微克(μg)', 'A', '称取的试样质量,单位为克(g)', 'm', '测定用吸取样液的体积,单位为毫升(mL)', 'V2', '提取后样液总体积,单位为毫升(mL)', 'V1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X =A/m*(V2/V1)）', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2477, '2517', 'X', '试样中硼酸的含量,单位为毫克每千克(mg/kg)', 'mg/kg', '由标准曲线得到的试样溶液中的硼酸的浓度,单位为微克(μg);', 'C', '试样定容体积,单位为毫升(mL)', 'V1', '试样的质量,单位为克(g);', 'm', '测定所量取的试样溶液的体积,单位为毫升(mL)。', 'V2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X =（C*1000*V1）/（m*1000*V2）', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2478, '2518', 'X', '试样中二氧化钛的含量', 'mg/kg', '由标准曲线得到的显色后试样溶液中钛的浓度,单位为微克每毫升(μg/mL)', 'c', '由标准曲线得到的显色后空白溶液中钛的浓度,单位为微克每毫升(μg/mL)', 'c0', '试样消解后初次定容的体积,单位为毫升(mL', 'V1', '试样质量,单位为克(g);', 'm', '显色时移取试样溶液的体积,单位为毫升(mL)', 'V2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X =(c-c0)*V1*50*1000/（m*V2 *1000）*1.6681', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2479, '2519', 'X', '木薯粉结果计算试样中氰化物(以 CN计)的含量', 'mg/kg', '测定试样溶液氰化物质量(以 CN- 计),单位为微克(μg);', 'A', '试样质量,单位为克(g)', 'm', '试样蒸馏液总体积,单位为毫升(mL)', 'V1', '测定用蒸馏液体积,单位为毫升(mL)', 'V2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X =A*1000/（m*V2/V1*1000）', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2480, '2520', 'X', '不蒸馏处理氰化物含量', 'mg/L', '测定试样溶液氰化物质量(以 CN- 计),单位为微克(μg);', 'A', '试样体积', 'V', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X =A*1000/（V*1000）', 'data:image/png;base64,', NULL);
