INSERT INTO `t_report_calculation_formulas` VALUES (2484, '2524', 'X', '试样中磷含量', '(mg/100g或 mg/100mL', '测定用试样溶液中磷的质量,单位为微克(μg)', 'm1', '测定用空白溶液中磷的质量,单位为微克(μg)', 'm0', '试样消化液定容体积,单位为毫升(mL)', 'V1', '试样称样量或移取体积,单位为克(g或 mL)', 'm', '测定用试样消化液的体积,单位为毫升(mL)', 'V2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X =(m1-m0)*V1/(m*V2)*100/1000', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2485, '2525', 'X', '试样中磷含量', '(mg/100g或 mg/100mL', '测定用试样溶液中磷的质量,单位为微克(μg)', 'ρ', '测定用空白溶液中磷的质量,单位为微克(μg)', 'ρ0', '试样消化液定容体积,单位为毫升(mL)', 'V', '试样称样量或移取体积,单位为克(g或 mL)', 'm', '测定用试样消化液的体积,单位为毫升(mL)', 'V1', '试样比色液定容体积,单位为毫升(mL)', 'V2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X =(ρ-ρ0)*V *V2/(m*V1*1000)*100', 'data:image/png;base64,', NULL);
