INSERT INTO `t_report_calculation_formulas` VALUES (2488, '2528', 'X', '试样中的酸价(以 KOH 计)', 'mg/g', '由标准曲线得到的试样溶液中总游离脂肪酸质量浓度(以油酸计),单位为毫克每毫升\n(mg/mL);', 'ρ', '油脂试样溶液的定容体积,单位为毫升(mL);', 'V', '油脂试样的取样量,单位为克(g);', 'm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X=ρ*V*56.1/(m*282.46)', 'data:image/png;base64,', NULL);
