INSERT INTO `t_report_calculation_formulas` VALUES (2492, '2534', 'ω1', '呈味核苷酸二钠含量(以干基计)的质量分数', '%', '试样溶液在250nm 处测得的吸光度;', 'A', '试样溶液在280nm 处测得的吸光度;', 'B', '试样的称样量,单位为克(g);', 'm', '试样的干燥减量,%;', 'ω4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ω1=((A-1.463*B)*254.55+(7.976*B-A)*47.769)/(m*5)*100/(100-ω4)*100%', 'data:image/png;base64,', NULL);
