INSERT INTO `t_report_calculation_formulas` VALUES (2501, '2541', 'E(1%1cm)', '吸光值(1%1cm)535nm', '(g/100mL)⁻¹·cm⁻¹', '实测试样溶液的吸光值', 'A', '甜菜红溶液浓度的数值，%', 'c', '比色杯溶液的厚度，单位cm', 'L', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E(0.1%1cm)=A/(c*L)', 'data:image/png;base64,', NULL);
