INSERT INTO `t_report_standard_detection` VALUES (2548, 'GB 7912-2010 栀子黄色阶', '食品安全检测', '单点光度法', 'UV-VIS', 'GB 7912-2010', '食品安全国家标准 食品添加剂 栀子黄', '栀子黄色阶', '1', NULL, '{\"波长1\":\"440±5\"}', '2010-12-21 00:00:00', NULL, NULL, '现行有效', '国家标准');
INSERT INTO `t_report_standard_pretreatment` VALUES (3821, '2447', '样品：参考表1称取适量试样（称准至0.001g）于100mL烧杯中，加入50mL水，搅拌溶解，定量转移至100mL容量瓶中，用水定容，混匀，为A溶液。移取10mLA溶液至50mL容量瓶中，加入15.0mL 2，4戊基二酮试剂，补水至总体积为40mL。\n标曲：分别定量移取0.1mL、0.5mL、1mL、2mL、5mL、10mL、15mL、20mL甲醛工作液至50mL容量瓶中，加15.0mL 2，4戊基二酮试剂，补水至总体积为40mL，混匀。置于60℃水浴中反应10min，取出冷却至室温，用异丙醇定容，混匀。用10mm比色皿，用空白溶液调零，于波长410nm下测试。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3822, '2448', '样品：称取0.1g试样于100mL烧杯内，加95%乙醇100mL溶解、搅拌，静止片刻，取清液作为待测试样。根据试样中防晒剂含量的大小，选择稀释倍数。\n测试：波长280nm~400nm，以95%乙醇作为空白，取试样进行扫描。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3823, '2449', '样品:准确称取一定量液体或固体样品，加适量热水超声萃取后，置于100mL三角烧瓶中，加入9倍体积的95%乙醇，4℃下静止12h，于4000r/min离心20min，弃去上去，将沉淀物用60℃热水50mL溶解，并用10mL热水洗涤离心管三次，合并沉淀物溶解液和洗涤液倒入100mL容量瓶中，放冷定容备用。\n标液：吸取葡萄糖标液0.25,0.50,1.00,1.50,2.00,2.50mL，分别置于50mL容量瓶中，加水定容。吸取上述溶液各2.00mL，再加苯酚液1.00mL，摇匀，迅速滴加硫酸5.00mL，摇匀后放置5min，置于沸水浴中加热15min，取出后冷却至室温，于490nm处以水作参比测吸光值。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3824, '2450', '准确称取一定量的液体样品，加水稀释到可溶性固形物为0.5%，或称取一定量的固体样品（精确至0.0001g），配成相应规定浓度水溶液，不断搅拌，使其完全溶解，备用。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3825, '2451', '准确移取一定量的液体样品，或称取一定量的固体样品（精确至0.0001g）加适量热水超声波萃取后，加到盛有60%FeCl3溶液1.0mL,盐酸6mL的150mL回流瓶中混匀，至沸水浴中加热回流4h，放冷，移至150mL分液漏斗中。用1mol/L NaOH溶液4mL和蒸馏水4mL依次洗涤回流瓶，一并倒入分液漏斗中。用CCl4定容至刻度，摇匀。准确吸取一定量的萃取液，置水浴上小心蒸干。准确吸取0.5%醋酸镁甲醇溶液10mL使之溶解。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3826, '2452', '准确移取一定量的液体样品，或称取一定量的固体样品（精确至0.0001g）加适量热水超声波萃取后，置于50mL锥形瓶，加水超声振荡萃取20min，冷却，定容至100mL，摇匀，于4000r/min离心20min，取上清液备用。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3827, '2453', '漂洗液制备：4g用250mg/kg硬水稀释定容至2000mL；清洗蔬菜后用250mg/kg硬水分别漂洗三次，2000mL、2000mL和1000mL；保持第三次漂洗水备用。以250mg/kg硬水作为空白样品。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3828, '2454', '漂洗液制备：4g用250mg/kg硬水稀释定容至2000mL；清洗蔬菜后用250mg/kg硬水分别漂洗三次，2000mL、2000mL和1000mL；保持第三次漂洗水备用。以250mg/kg硬水作为空白样品。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3829, '2455', '漂洗液制备：4g用250mg/kg硬水稀释定容至2000mL；清洗蔬菜后用250mg/kg硬水分别漂洗三次，2000mL、2000mL和1000mL；保持第三次漂洗水备用。以250mg/kg硬水作为空白样品。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3830, '2456', '漂洗液制备：4g用250mg/kg硬水稀释定容至2000mL；清洗蔬菜后用250mg/kg硬水分别漂洗三次，2000mL、2000mL和1000mL；保持第三次漂洗水备用。以250mg/kg硬水作为空白样品。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3831, '2457', '准确称取试样5.0g，用5mL冰醋酸润湿，加5mL水，用玻璃杯搅拌样品完全溶解。搅拌条件下缓慢加入50mL丙酮，1g氯化钠，搅拌数分钟确保完全沉淀。用少量丙酮润湿滤纸，过滤样品溶液，收集滤液至100mL容量瓶，用30mL丙酮将样品全部转移到滤纸并冲洗残渣过滤，用丙酮定容至100mL.');
INSERT INTO `t_report_standard_pretreatment` VALUES (3832, '2458', '试样加100mL水，加热溶解，搅拌下滴加盐酸溶液调水相pH到2以下。待物理冷却到30～40℃后加入石油醚50mL，将此混合溶液转移至250mL的分液漏斗中，并用水50mL冲洗烧杯，静置分层；下层水相放入250mL容量瓶，合并石油醚到同一分液漏斗，再用30mL水洗涤，合并后的石油醚一次，将水相合并到上述同一容量瓶中，用水定容，进行磷酸盐的测定。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3833, '2459', '量取200mL水样置于锥形瓶中，加入硫酸锌溶液2mL，在搅拌下滴加氢氧化钠溶液，调节pH等于7。或将200mL水样调节pH=7，加4mL氢氧化铝悬浮液。待絮凝胶团下沉后，吸取上清液，注入吸附树脂柱中，以1～2滴每秒的流速流出。先用100mL水样上清分两次洗涤柱子，弃去。再使水样上清液通过柱子，收集50mL于比色管中，备测。树脂用150mL水分三次洗涤备用。 在盛有水样的比色管中加入1mL盐酸溶液，0.1mL氨基苯磺酸溶液。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3834, '2460', '乙酸锌过滤分离；过滤-酸化-吹气分离。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3835, '2461', '微孔滤膜抽滤将叶绿素浓缩，放-20℃冰箱保存；提取放-40℃冰箱20min，取出室温放置5min，反复3次。加入10mL90%丙酮溶液，剧烈震荡，放4℃冰箱避光浸泡4～12h（震摇2～3次）。离心后测试。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3836, '2462', '微孔滤膜抽滤将叶绿素浓缩，放-20℃冰箱保存；提取放-40℃冰箱20min，取出室温放置5min，反复3次。加入10mL90%丙酮溶液，剧烈震荡，放4℃冰箱避光浸泡4～12h（震摇2～3次）。离心后测试。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3837, '2463', '微孔滤膜抽滤将叶绿素浓缩，放-20℃冰箱保存；提取放-40℃冰箱20min，取出室温放置5min，反复3次。加入10mL90%丙酮溶液，剧烈震荡，放4℃冰箱避光浸泡4～12h（震摇2～3次）。离心后测试。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3838, '2464', '取适量清澈透明试样（必要时过滤）；');
INSERT INTO `t_report_standard_pretreatment` VALUES (3839, '2465', '对含硼量为0.10～1.0mg/L的水样，取1.00mL，若水样含硼量过高，则应先行稀释。若含硼量过低，可吸取较多的水样，移入聚乙烯烧杯中，加入少许饱和氢氧化钙溶液，调pH至9，在水浴上蒸发至干。加入适当体积1mol/L盐酸溶液溶解，加水至1mL待测。水样浑浊则需要过滤。');
INSERT INTO `t_report_standard_pretreatment` VALUES (3840, '2466', '样品：取样，稀释定容（浊度大于100度），检测\n标曲：取标液，稀释定容，检测');
INSERT INTO `t_report_standard_pretreatment` VALUES (3841, '2467', '样品：取样，调pH值，加液，萃取（2次萃取），检测\n标曲：取样，稀释定容，调pH值，加液，萃取（2次萃取），检测');
INSERT INTO `t_report_standard_pretreatment` VALUES (3842, '2468', '样品：取样，萃取（2次萃取），检测; 空白样品加标，按样品方法进行萃取确定萃取系数。\n标曲：取样，稀释定容，检测');
INSERT INTO `t_report_standard_pretreatment` VALUES (3843, '2469', '样品：取样，稀释定容，加液，沸水浴，冷却，检测\n标曲：取标液，稀释定容，加液，沸水浴，冷却，检测');
INSERT INTO `t_report_standard_pretreatment` VALUES (3844, '2470', '样品：取样，稀释定容，加液，定时显色，检测\n标曲：取标液，稀释定容，加液，定时显色，检测');
INSERT INTO `t_report_standard_pretreatment` VALUES (3845, '2471', '样品：取样（1直接取样；2稀释后测试；），加液，定时显色，检测\n标曲：取标液，稀释定容，加液，定时显色，检测');
